examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true }, variant = MonarchButtonVariant.Primary)
if (open) {
    // While the workspace is created, a swipe, back or a tap outside does not close the sheet.
    MonarchBottomSheet(onDismissRequest = { open = false }, dismissible = !creating) {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                MonarchText(
                    text = {{title}},
                    modifier = Modifier.weight(1f),
                    style = MonarchTextStyle.Heading,
                    heading = true,
                )
                MonarchButton(
                    text = {{cancel}},
                    onClick = { open = false },
                    variant = MonarchButtonVariant.Ghost,
                    enabled = !creating,
                )
            }
            MonarchTextField(value = name, onValueChange = { name = it }, label = {{name.label}}, placeholder = {{name.value}}, errorText = nameError, required = true)
            MonarchUsernameAvailabilityInput(
                value = username,
                label = {{username.label}},
                onValueChange = { username = it },
                validate = { handle ->
                    // Call the product's availability lookup here.
                    if (handle.lowercase() == {{username.taken}}) {
                        MonarchUsernameAvailabilityResult(valid = false, message = {{username.takenMessage}})
                    } else {
                        MonarchUsernameAvailabilityResult(valid = true)
                    }
                },
                placeholder = {{username.prompt}},
                helperText = {{username.helper}},
                prefix = {{username.prefix}},
                required = true,
                onStatusChange = { status, _ -> usernameStatus = status },
            )
            MonarchRadioCardGroup(
                options = listOf(
                    MonarchRadioCardOption({{type.options.0.id}}, title = {{type.options.0.title}}, description = {{type.options.0.description}}, icon = { MonarchIcon(SampleIcons.Person, contentDescription = null) }),
                    MonarchRadioCardOption({{type.options.1.id}}, title = {{type.options.1.title}}, description = {{type.options.1.description}}, icon = { MonarchIcon(SampleIcons.Building, contentDescription = null) }),
                ),
                selected = type,
                onSelect = { type = it },
                label = {{type.label}},
                columns = 2,
                layout = MonarchRadioCardLayout.Tile,
            )
            MonarchButton(
                text = {{submit}},
                onClick = {
                    submitted = true
                    val valid = name.trim().length in 4..25 && type != null
                    if (valid && usernameStatus == MonarchUsernameAvailabilityStatus.Valid) {
                        creating = true
                        scope.launch {
                            // Create the workspace on the server here.
                            creating = false
                            open = false
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
                loading = creating,
            )
        }
    }
}

examples.setupTemplate:
var open by rememberSaveable { mutableStateOf(true) }
var name by rememberSaveable { mutableStateOf({{name.value}}) }
var username by rememberSaveable { mutableStateOf("") }
var type by rememberSaveable { mutableStateOf<String?>({{type.value}}) }
var usernameStatus by remember { mutableStateOf(MonarchUsernameAvailabilityStatus.Idle) }
var submitted by rememberSaveable { mutableStateOf(false) }
var creating by remember { mutableStateOf(false) }
val scope = rememberCoroutineScope()
val nameError = if (submitted && name.trim().length !in 4..25) "Use 4 to 25 characters" else null

