            MonarchTextField(value = name, onValueChange = { name = it }, label = "Workspace name", placeholder = "Acme Inc.", errorText = nameError, required = true)
            MonarchUsernameAvailabilityInput(
                value = username,
                label = "Workspace username",
                onValueChange = { username = it },
                validate = { handle ->
                    // Call the product's availability lookup here.
                    if (handle.lowercase() == "acmeinc") {
                        MonarchUsernameAvailabilityResult(valid = false, message = "That username is taken")
                    } else {
                        MonarchUsernameAvailabilityResult(valid = true)
                    }
                },
                placeholder = "acme",
                helperText = "Letters and numbers only, 5 to 30 characters.",
                prefix = "@",
                required = true,
                onStatusChange = { status, _ -> usernameStatus = status },
            )
            MonarchRadioCardGroup(
                options = listOf(
                    MonarchRadioCardOption("creator", title = "Creator", description = "For individual creators and personal projects", icon = { MonarchIcon(SampleIcons.Person, contentDescription = null) }),
                    MonarchRadioCardOption("business", title = "Business", description = "For teams and companies", icon = { MonarchIcon(SampleIcons.Building, contentDescription = null) }),
                ),
                selected = type,
                onSelect = { type = it },
                label = "Type",
                columns = 2,
                layout = MonarchRadioCardLayout.Tile,
            )
            MonarchButton(
                text = "Create workspace",
                onClick = {
                    submitted = true
                    val valid = name.trim().length in 4..25 && type != null
                    if (valid && usernameStatus == MonarchUsernameAvailabilityStatus.Valid) {
                        creating = true
                        scope.launch {
                            // Create the workspace on the server here.
                            creating = false
                            open = false
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
                loading = creating,
            )
        }
    }
}
